        result = Vector256.MultiplyAddEstimate(Vector256.ShuffleNative(right, Vector256.Create(3L, 2L, 1L, 0L)) * left.GetElement(0), Vector256.Create(+1.0, -1.0, +1.0, -1.0), result);
